   135	function removeWaypoint(transaction: OnyxEntry<Transaction>, currentIndex: string, isDraft?: boolean): Promise<void | void[]> {
   136	    // Index comes from the route params and is a string
   137	    const index = Number(currentIndex);
   138	    const existingWaypoints = transaction?.comment?.waypoints ?? {};
   139	    const totalWaypoints = Object.keys(existingWaypoints).length;
   140	
   141	    const waypointValues = Object.values(existingWaypoints);
   142	    const removed = waypointValues.splice(index, 1);
   143	    if (removed.length === 0) {
   144	        return Promise.resolve();
   145	    }
   146	
   147	    const isRemovedWaypointEmpty = removed.length > 0 && !TransactionUtils.waypointHasValidAddress(removed[0] ?? {});
   148	
   149	    // When there are only two waypoints we are adding empty waypoint back
   150	    if (totalWaypoints === 2 && (index === 0 || index === totalWaypoints - 1)) {
   151	        waypointValues.splice(index, 0, {});
   152	    }
   153	
   154	    const reIndexedWaypoints: WaypointCollection = {};
   155	    waypointValues.forEach((waypoint, idx) => {
   156	        reIndexedWaypoints[`waypoint${idx}`] = waypoint;
   157	    });
