   159	    // Onyx.merge won't remove the null nested object values, this is a workaround
   160	    // to remove nested keys while also preserving other object keys
   161	    // Doing a deep clone of the transaction to avoid mutating the original object and running into a cache issue when using Onyx.set
   162	    let newTransaction: Transaction = {
   163	        // eslint-disable-next-line @typescript-eslint/non-nullable-type-assertion-style
   164	        ...(transaction as Transaction),
   165	        comment: {
   166	            ...transaction?.comment,
   167	            waypoints: reIndexedWaypoints,
   168	        },
   169	        // We want to reset the amount only for draft transactions (when creating the expense).
   170	        // When modifying an existing transaction, the amount will be updated on the actual IOU update operation.
   171	        ...(isDraft && {amount: CONST.IOU.DEFAULT_AMOUNT}),
   172	    };
   173	
   174	    if (!isRemovedWaypointEmpty) {
   175	        newTransaction = {
   176	            ...newTransaction,
